import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

function Anomalies() {
    const navigate = useNavigate();
    const [anomalies, setAnomalies] = useState([]);
    const [loading, setLoading] = useState(true);

    const fetchAnomalies = () => {
        fetch('http://localhost:8000/api/anomalies/')
            .then(res => res.json())
            .then(data => {
                setAnomalies(data);
                setLoading(false);
            })
            .catch(err => {
                console.error('Error:', err);
                setLoading(false);
            });
    };

    useEffect(() => {
        fetchAnomalies();
    }, []);

    const handleAction = async (id, action) => {
        try {
            const response = await fetch(`http://localhost:8000/api/anomalies/${id}/${action}/`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                }
            });
            const data = await response.json();
            if (response.ok) {
                alert(data.message);
                fetchAnomalies(); // رفرش لیست
            } else {
                alert(data.message);
            }
        } catch (error) {
            alert('❌ خطا در انجام عملیات!');
            console.error('Error:', error);
        }
    };

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
                <h1>📋 لیست آنومالی‌ها</h1>
                <button
                    onClick={() => navigate('/anomalies/new')}
                    style={{
                        padding: '10px 20px',
                        backgroundColor: '#1976d2',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: 'pointer'
                    }}
                >
                    + ثبت آنومالی جدید
                </button>
            </div>

            {loading ? (
                <p>⏳ در حال بارگذاری...</p>
            ) : (
                <table style={{ width: '100%', borderCollapse: 'collapse', backgroundColor: 'white', borderRadius: '8px' }}>
                    <thead>
                        <tr style={{ backgroundColor: '#f5f5f5' }}>
                            <th style={{ padding: '12px', textAlign: 'right' }}>عنوان</th>
                            <th style={{ padding: '12px', textAlign: 'right' }}>مکان</th>
                            <th style={{ padding: '12px', textAlign: 'right' }}>سطح ریسک</th>
                            <th style={{ padding: '12px', textAlign: 'right' }}>وضعیت</th>
                            <th style={{ padding: '12px', textAlign: 'center' }}>عملیات</th>
                        </tr>
                    </thead>
                    <tbody>
                        {anomalies.length === 0 ? (
                            <tr>
                                <td colSpan="5" style={{ textAlign: 'center', padding: '20px', color: '#666' }}>
                                    هیچ آنومالی ثبت نشده است
                                </td>
                            </tr>
                        ) : (
                            anomalies.map((anomaly) => (
                                <tr key={anomaly.id} style={{ borderBottom: '1px solid #eee' }}>
                                    <td style={{ padding: '12px' }}>{anomaly.title}</td>
                                    <td style={{ padding: '12px' }}>{anomaly.location}</td>
                                    <td style={{ padding: '12px' }}>
                                        <span style={{
                                            padding: '4px 12px',
                                            borderRadius: '12px',
                                            backgroundColor: anomaly.risk_level === 'critical' ? '#ffebee' : 
                                                           anomaly.risk_level === 'high' ? '#fff3e0' : '#e8f5e9',
                                            color: anomaly.risk_level === 'critical' ? '#c62828' : 
                                                   anomaly.risk_level === 'high' ? '#e65100' : '#2e7d32'
                                        }}>
                                            {anomaly.risk_level}
                                        </span>
                                    </td>
                                    <td style={{ padding: '12px' }}>
                                        <span style={{
                                            padding: '4px 12px',
                                            borderRadius: '12px',
                                            backgroundColor: anomaly.status === 'closed' ? '#e8f5e9' :
                                                           anomaly.status === 'new' ? '#e3f2fd' : '#fff3e0',
                                            color: anomaly.status === 'closed' ? '#2e7d32' :
                                                   anomaly.status === 'new' ? '#0d47a1' : '#e65100'
                                        }}>
                                            {anomaly.status}
                                        </span>
                                    </td>
                                    <td style={{ padding: '12px', textAlign: 'center' }}>
                                        <div style={{ display: 'flex', gap: '5px', justifyContent: 'center', flexWrap: 'wrap' }}>
                                            {anomaly.status === 'new' && (
                                                <button
                                                    onClick={() => handleAction(anomaly.id, 'approve')}
                                                    style={{
                                                        padding: '5px 10px',
                                                        backgroundColor: '#1976d2',
                                                        color: 'white',
                                                        border: 'none',
                                                        borderRadius: '4px',
                                                        cursor: 'pointer',
                                                        fontSize: '12px'
                                                    }}
                                                >
                                                    ✅ تأیید
                                                </button>
                                            )}
                                            {anomaly.status === 'approved' && (
                                                <button
                                                    onClick={() => handleAction(anomaly.id, 'assign')}
                                                    style={{
                                                        padding: '5px 10px',
                                                        backgroundColor: '#ff9800',
                                                        color: 'white',
                                                        border: 'none',
                                                        borderRadius: '4px',
                                                        cursor: 'pointer',
                                                        fontSize: '12px'
                                                    }}
                                                >
                                                    📌 تخصیص
                                                </button>
                                            )}
                                            {anomaly.status === 'assigned' && (
                                                <button
                                                    onClick={() => handleAction(anomaly.id, 'resolve')}
                                                    style={{
                                                        padding: '5px 10px',
                                                        backgroundColor: '#4caf50',
                                                        color: 'white',
                                                        border: 'none',
                                                        borderRadius: '4px',
                                                        cursor: 'pointer',
                                                        fontSize: '12px'
                                                    }}
                                                >
                                                    🔧 رفع
                                                </button>
                                            )}
                                            {anomaly.status === 'resolved' && (
                                                <button
                                                    onClick={() => handleAction(anomaly.id, 'close')}
                                                    style={{
                                                        padding: '5px 10px',
                                                        backgroundColor: '#9c27b0',
                                                        color: 'white',
                                                        border: 'none',
                                                        borderRadius: '4px',
                                                        cursor: 'pointer',
                                                        fontSize: '12px'
                                                    }}
                                                >
                                                    🔒 بستن
                                                </button>
                                            )}
                                            {anomaly.status === 'closed' && (
                                                <span style={{ color: '#2e7d32', fontWeight: 'bold' }}>
                                                    ✅ بسته شد
                                                </span>
                                            )}
                                        </div>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            )}
        </div>
    );
}

export default Anomalies;
